-- Run in the Supabase SQL editor. Enable RLS before exposing the app publicly.
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null check (char_length(full_name) between 2 and 80), headline text, bio text check (char_length(bio) <= 2000), location text, availability text not null default 'open_to_talk' check (availability in ('available_now','open_to_talk','unavailable')), website_url text check (website_url is null or website_url ~ '^https://'), is_public boolean not null default true, created_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, title text not null check (char_length(title) between 2 and 120), description text check (char_length(description) <= 3000), repository_url text check (repository_url is null or repository_url ~ '^https://'), demo_url text check (demo_url is null or demo_url ~ '^https://'), created_at timestamptz not null default now());
create table public.connection_requests (id uuid primary key default gen_random_uuid(), sender_id uuid not null references public.profiles(id) on delete cascade, recipient_id uuid not null references public.profiles(id) on delete cascade, status text not null default 'pending' check (status in ('pending','accepted','declined')), created_at timestamptz not null default now(), unique(sender_id, recipient_id), check (sender_id <> recipient_id));
create index projects_owner_idx on public.projects(owner_id); create index connections_recipient_idx on public.connection_requests(recipient_id,status);
alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.connection_requests enable row level security;
create policy "public profiles readable" on public.profiles for select using (is_public or id = auth.uid()); create policy "owners update profiles" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid()); create policy "owners create profiles" on public.profiles for insert with check (id = auth.uid());
create policy "public projects readable" on public.projects for select using (true); create policy "owners manage projects" on public.projects for all using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy "participants read requests" on public.connection_requests for select using (sender_id = auth.uid() or recipient_id = auth.uid()); create policy "send own requests" on public.connection_requests for insert with check (sender_id = auth.uid()); create policy "recipients respond" on public.connection_requests for update using (recipient_id = auth.uid()) with check (recipient_id = auth.uid());
